from taf.nms.nom.schemas.base import SchemaObject, SchemaField
from taf.nms.nom.schemas.cm.managed_objects_mo_class_mo_class import ManagedObjectsMoClassMoClass


class ManagedObjectsInfo(SchemaObject):
    mo_id = SchemaField(name="mo_id", not_null=True)
    mo_class = SchemaField(name="mo_class", not_null=True, klass=ManagedObjectsMoClassMoClass)
    operation = SchemaField(name="operation")
    parameters = SchemaField(name="parameters")

    def __init__(self, mo_id, mo_class, operation, parameters):
        self.mo_id = mo_id
        self.mo_class = mo_class
        self.operation = operation
        self.parameters = parameters
        super(ManagedObjectsInfo, self).__init__()
